begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
\ir helpers/phase11_fixtures.sql
\ir helpers/phase15_scenarios.sql
update public.tenants set slug='phase15-sandbox-pgtap' where id='e3200000-0000-4000-8000-000000000001';
create temp table p15(k text primary key,v jsonb);grant all on p15 to authenticated;
insert into p15 values('seed',pg_temp.phase15_seed('e3200000-0000-4000-8000-000000000001','e3100000-0000-4000-8000-000000000001','e1500000-0000-4000-8000-000000000001'));
select set_config('request.jwt.claim.sub','e3100000-0000-4000-8000-000000000001',true);
set local role authenticated;
insert into p15 values('live',public.admin_analytics_workspace('e3200000-0000-4000-8000-000000000001',current_date-30,current_date+1,'LIVE'));
insert into p15 values('sandbox',public.admin_analytics_workspace('e3200000-0000-4000-8000-000000000001',current_date-30,current_date+1,'SANDBOX'));
select is((select v->>'operational_scope' from p15 where k='live'),'SANDBOX','financial LIVE never reclassifies sandbox operational data');
select is((select v->'sources'->>'receipts' from p15 where k='live'),'0','test invoices are not live receipts');
select ok(not exists(select 1 from p15 cross join lateral jsonb_array_elements(v->'money') m where k='live' and m->>'kind' in ('collected','mrr','arr')),'no live revenue or MRR from test prices/periods');
select is((select x->>'status' from p15 cross join lateral jsonb_array_elements(v->'metrics') x where k='live' and x->>'id'='collected'),'UNAVAILABLE','missing received amounts are unavailable, not zero');
select is((select x->>'value' from p15 cross join lateral jsonb_array_elements(v->'metrics') x where k='live' and x->>'id'='margin'),null::text,'unknown cost cannot become 100% margin');
select is((select (x->>'amount')::numeric from p15 cross join lateral jsonb_array_elements(v->'money') x where k='sandbox' and x->>'kind'='collected' and x->>'currency'='USDT'),12345678901234567.890123::numeric,'exact numeric atomic-unit conversion, no offer-price substitution');
select is((select (x->>'amount')::numeric from p15 cross join lateral jsonb_array_elements(v->'money') x where k='sandbox' and x->>'kind'='collected' and x->>'currency'='XTR'),100::numeric,'XTR separate from USDT');
select is((select count(*) from p15 cross join lateral jsonb_array_elements(v->'money') x where k='sandbox' and x->>'kind'='collected'),2::bigint,'no FX or combined currency total');
select is((select (x->>'amount')::numeric from p15 cross join lateral jsonb_array_elements(v->'money') x where k='sandbox' and x->>'kind'='mrr' and x->>'currency'='USDT'),12345678901234567.890123::numeric,'calendar-month MRR derives from evidenced period, not mutable price');
select is((select x->>'amount' from p15 cross join lateral jsonb_array_elements(v->'money') x where k='sandbox' and x->>'kind'='mrr' and x->>'currency'='XTR'),null::text,'fixed-day MRR has no invented month length');
select is((select (x->>'value')::numeric from p15 cross join lateral jsonb_array_elements(v->'metrics') x where k='sandbox' and x->>'id'='active_subscriptions'),2::numeric,'same customer can have two evidenced plans');
select is((select x->>'value' from p15 cross join lateral jsonb_array_elements(v->'metrics') x where k='sandbox' and x->>'id'='renewal_events'),'1','multiple periods count one renewal not two purchases');
select is((select (x->>'value')::numeric from p15 cross join lateral jsonb_array_elements(v->'metrics') x where k='sandbox' and x->>'id'='billing_coverage'),2::numeric/3,'missing third cost reduces coverage');
select is((select (x->>'amount')::numeric from p15 cross join lateral jsonb_array_elements(v->'money') x where k='sandbox' and x->>'kind'='ai_cost'),0.30000003::numeric,'model invocation costs not added again from agent_runs');
select ok(not exists(select 1 from p15 cross join lateral jsonb_array_elements(v->'money') x where k='sandbox' and x->>'kind'='cost_per_operation'),'incomplete run billing leaves operation economics unavailable');
select is((select x->>'value' from p15 cross join lateral jsonb_array_elements(v->'metrics') x where k='sandbox' and x->>'id'='outbound'),'0','generated/failed/pending drafts are not provider delivery');
select is((select x->>'value' from p15 cross join lateral jsonb_array_elements(v->'metrics') x where k='sandbox' and x->>'id'='failed_deliveries'),'1','failed draft recorded as workload not delivery');
select is((select (v->'funnel'->0->>'count')::int from p15 where k='sandbox'),3,'cohort deduplicates two mapped contacts, retains two unmatched contacts');
select is((select (v->'funnel'->1->>'count')::int from p15 where k='sandbox'),1,'verified person appears only once across offers and contacts');
select is((select (v->'funnel'->3->>'count')::int from p15 where k='sandbox'),1,'two offers do not create two customers');
select ok(not exists(select 1 from p15 cross join lateral jsonb_array_elements(v->'funnel') x where k='live' and (x->>'count')::int>0),'no live acquisition cohort without provenance');
select throws_ok($$select public.admin_analytics_workspace('e3200000-0000-4000-8000-000000000002',current_date-30,current_date+1,'LIVE')$$,'42501','analytics permission denied','cross tenant read denied');
select throws_ok($$select public.admin_analytics_workspace('e3200000-0000-4000-8000-000000000001',current_date,current_date,'LIVE')$$,'22023','analytics period invalid','empty interval denied');
select throws_ok($$select public.admin_analytics_workspace('e3200000-0000-4000-8000-000000000001',current_date-367,current_date+1,'LIVE')$$,'22023','analytics period invalid','unbounded interval denied');
select throws_ok($$select public.admin_analytics_sources('e3200000-0000-4000-8000-000000000001',current_date-30,current_date+1,'SANDBOX','invocations','stale')$$,'PT409','analytics source changed','stale source fingerprint rejected');
select ok((public.admin_analytics_sources('e3200000-0000-4000-8000-000000000001',current_date-30,current_date+1,'SANDBOX','invocations',(select v->>'fingerprint' from p15 where k='sandbox'))->'rows'->0) ?& array['id','source','at','state'],'bounded source lineage fields available');
select ok(not (public.admin_analytics_sources('e3200000-0000-4000-8000-000000000001',current_date-30,current_date+1,'SANDBOX','invocations',(select v->>'fingerprint' from p15 where k='sandbox'))::text~'provider_request_id|request_fingerprint|content|customer_id'),'source drilldown omits private/customer payload');
select set_config('request.jwt.claim.sub','e3100000-0000-4000-8000-000000000002',true);
select throws_ok($$select public.admin_analytics_workspace('e3200000-0000-4000-8000-000000000001',current_date-30,current_date+1,'LIVE')$$,'42501','analytics permission denied','support cannot read financial analytics');
select set_config('request.jwt.claim.sub','e3100000-0000-4000-8000-000000000003',true);
select throws_ok($$select public.admin_analytics_workspace('e3200000-0000-4000-8000-000000000001',current_date-30,current_date+1,'LIVE')$$,'42501','analytics permission denied','readonly denied');
reset role;
select is(private.analytics_monthly(1200,'{"billing":"recurring","duration_unit":"calendar_year","duration_count":1}'),100::numeric,'annual recurring exact monthly equivalent');
select is(private.analytics_monthly(900,'{"billing":"recurring","duration_unit":"calendar_month","duration_count":3}'),300::numeric,'multi-month calendar normalization');
select is(private.analytics_monthly(30,'{"billing":"recurring","duration_unit":"fixed_days","duration_count":30}'),null::numeric,'fixed days not silently calendar month');
select is(private.analytics_monthly(30,'{"billing":"one_off","duration_unit":"calendar_month","duration_count":1}'),null::numeric,'one off price never MRR');
select is(public.subscription_expiry('2028-01-31 10:00Z','{"duration_unit":"calendar_month","duration_count":1}'),'2028-02-29 10:00Z'::timestamptz,'existing exact calendar-month boundary preserved');
select ok(not has_function_privilege('anon','public.admin_analytics_workspace(uuid,date,date,text,uuid)','execute'),'anonymous analytics API denied');
select ok(not has_table_privilege('service_role','private.analytics_cost_evidence','insert'),'service cannot insert reviewed economic authority');
select ok(not has_function_privilege('authenticated','private.analytics_money(uuid,date,date,text)','execute'),'private analytics money not a browser bypass');
update public.tenant_members set role='analyst' where tenant_id='e3200000-0000-4000-8000-000000000001' and user_id='e3100000-0000-4000-8000-000000000003';
set local role authenticated;select set_config('request.jwt.claim.sub','e3100000-0000-4000-8000-000000000003',true);
select lives_ok($$select public.admin_analytics_workspace('e3200000-0000-4000-8000-000000000001',current_date-30,current_date+1,'LIVE')$$,'analyst permitted tenant-safe aggregates');
select throws_ok($$select public.admin_analytics_cost_submit('e3200000-0000-4000-8000-000000000001',gen_random_uuid(),'SUPPLIER','ASSUMPTION','12','USD',current_date-30,current_date,'SYNTHETIC source',null)$$,'42501','analytics permission denied','analyst cannot create economic assumptions');
select set_config('request.jwt.claim.sub','e3100000-0000-4000-8000-000000000001',true);
insert into p15 values('cost',to_jsonb(public.admin_analytics_cost_submit('e3200000-0000-4000-8000-000000000001','e1500000-0000-4000-8000-000000000002','SUPPLIER','ASSUMPTION','12.00000001','USD',current_date-30,current_date,'SYNTHETIC source; not actual cost',null)));
select is(public.admin_analytics_cost_submit('e3200000-0000-4000-8000-000000000001','e1500000-0000-4000-8000-000000000002','SUPPLIER','ASSUMPTION','12.00000001','USD',current_date-30,current_date,'SYNTHETIC source; not actual cost',null),((select v from p15 where k='cost')#>>'{}')::uuid,'same economic request idempotent');
select throws_ok($$select public.admin_analytics_cost_submit('e3200000-0000-4000-8000-000000000001','e1500000-0000-4000-8000-000000000002','SUPPLIER','ASSUMPTION','99','USD',current_date-30,current_date,'SYNTHETIC source; not actual cost',null)$$,'PT409','economic request conflict','request id cannot rebind different amount');
select is(public.admin_analytics_cost_review('e3200000-0000-4000-8000-000000000001',((select v from p15 where k='cost')#>>'{}')::uuid,1,true),2,'owner-reviewed economic evidence revision advances');
select throws_ok($$select public.admin_analytics_cost_review('e3200000-0000-4000-8000-000000000001',((select v from p15 where k='cost')#>>'{}')::uuid,1,false)$$,'PT409','economic review conflict','stale concurrent review rejected');
reset role;
select is((select count(*) from public.audit_logs where action='analytics.cost_reviewed' and tenant_id='e3200000-0000-4000-8000-000000000001'),1::bigint,'economic review audited once');
select is((select count(*) from private.verified_payment_receipts),0::bigint,'economic review never creates receipt');
select is((select count(*) from public.subscriptions where mode='live'),0::bigint,'no live subscription from analytics');
select is((select count(*) from public.channel_access where mode='live'),0::bigint,'no live VIP from analytics');
select is((select count(*) from public.escalation_notifications),0::bigint,'no manager alert from analytics');
-- Additional negative provenance, unknown denominator, billing replay and privacy scenarios.
select is((private.analytics_metric('missing',null,'ratio',0,0)->>'status'),'UNAVAILABLE','zero denominator remains unavailable');
select is((private.analytics_metric('true_zero',0)->>'status'),'AVAILABLE','observed zero differs from unknown');
insert into public.model_invocations(tenant_id,run_id,provider,model,status,provider_request_id,input_tokens,output_tokens,billed_amount,billed_currency,latency_ms,request_fingerprint,created_at,invocation_sequence) select tenant_id,run_id,provider,model,status,provider_request_id,input_tokens,output_tokens,billed_amount,billed_currency,latency_ms,request_fingerprint,created_at,2 from public.model_invocations where tenant_id='e3200000-0000-4000-8000-000000000001' and provider_request_id is not null;
select is((select count(*) from jsonb_array_elements(private.analytics_money('e3200000-0000-4000-8000-000000000001',current_date-30,current_date+1,'SANDBOX')) x where x->>'kind'='ai_cost'),0::bigint,'duplicate provider request excluded rather than billed twice');
select is((select (x->>'value')::numeric from jsonb_array_elements(private.analytics_metrics('e3200000-0000-4000-8000-000000000001',current_date-30,current_date+1,'SANDBOX')) x where x->>'id'='billing_coverage'),0::numeric,'duplicate provider evidence reduces billing coverage to zero');
select throws_ok(format('select public.admin_analytics_sources(%L,current_date-30,current_date+1,%L,%L,%L)','e3200000-0000-4000-8000-000000000001','SANDBOX','invocations',(select v->>'fingerprint' from p15 where k='sandbox')),'PT409','analytics source changed','concurrent source revision cannot reuse earlier chart drilldown');
update public.subscriptions set state='CANCELLED' where id=((select v from p15 where k='seed')->>'fixed_subscription')::uuid;
select is((select x->>'value' from jsonb_array_elements(private.analytics_metrics('e3200000-0000-4000-8000-000000000001',current_date-30,current_date+1,'SANDBOX')) x where x->>'id'='cancelled'),'1','effective CANCELLED state counted');
select is((select x->>'value' from jsonb_array_elements(private.analytics_metrics('e3200000-0000-4000-8000-000000000001',current_date-30,current_date+1,'SANDBOX')) x where x->>'id'='expired'),'0','cancellation not conflated with expiration');
select is((select count(*) from private.analytics_periods('e3200000-0000-4000-8000-000000000001','SANDBOX')),3::bigint,'immutable evidence keeps three periods, no duplicate join fan-out');
select is((select (x->>'value')::numeric from jsonb_array_elements(private.analytics_metrics('e3200000-0000-4000-8000-000000000001',current_date-30,current_date,'SANDBOX')) x where x->>'id'='customer_churn'),0::numeric,'customer with two plans retained once by end-period coverage');
-- A local-only, rolled-back receipt still lacks an authoritative amount. No activation gate is opened.
insert into p15 values('local_receipt',to_jsonb(gen_random_uuid()));
insert into p15 values('local_receipt_event',to_jsonb(private.append_domain_event('e3200000-0000-4000-8000-000000000001','e3300000-0000-4000-8000-000000000001','payment.confirmed',1,jsonb_build_object('payment_id',(select v#>>'{}' from p15 where k='local_receipt'),'tx_hash','synthetic:local-only'),'SYSTEM',null,'payment_verifier','TRUSTED',gen_random_uuid(),null,'p15:local:rollback',now())));
insert into private.verified_payment_receipts(id,tenant_id,customer_id,offer_id,event_id,provider_id,provider_reference,signature_verified,independent_verified,evidence_hash,verified_at) values(((select v from p15 where k='local_receipt')#>>'{}')::uuid,'e3200000-0000-4000-8000-000000000001','e3300000-0000-4000-8000-000000000001','e3600000-0000-4000-8000-000000000001',((select v from p15 where k='local_receipt_event')#>>'{}')::uuid,'local-only','synthetic:local-only',true,true,repeat('f',64),now());
select is((public.admin_analytics_workspace('e3200000-0000-4000-8000-000000000001',current_date-30,current_date+1,'LIVE')->'sources'->>'incomplete_receipt_amounts'),'1','even independent receipt has unavailable amount lineage');
select ok(not exists(select 1 from jsonb_array_elements(private.analytics_money('e3200000-0000-4000-8000-000000000001',current_date-30,current_date+1,'LIVE')) x where x->>'kind'='collected'),'receipt identity/offer value cannot invent cash');
select throws_ok($$insert into private.verified_payment_receipts select gen_random_uuid(),tenant_id,customer_id,offer_id,event_id,provider_id,provider_reference,signature_verified,independent_verified,evidence_hash,verified_at from private.verified_payment_receipts$$,'23505',null,'duplicate receipt/event cannot double count');
insert into public.survey_versions(id,tenant_id,survey_id,version,definition,owner_id) values('e1500000-0000-4000-8000-000000000010','e3200000-0000-4000-8000-000000000001',gen_random_uuid(),1,'{"title":"Synthetic analytics privacy","language":"en","audience":"ALL","trigger":"REQUESTED","privacy":"ANONYMOUS","questions":[{"id":"q1","type":"RATING","topic":"VALUE","label":"Value?","choices":[]},{"id":"q2","type":"RATING","topic":"SUPPORT","label":"Support?","choices":[]},{"id":"q3","type":"RATING","topic":"SIGNAL","label":"Clarity?","choices":[]},{"id":"q4","type":"RATING","topic":"RENEWAL","label":"Renewal?","choices":[]}]}','e3100000-0000-4000-8000-000000000001');
insert into private.survey_anonymous_responses(tenant_id,version_id,collection_month,answers) select 'e3200000-0000-4000-8000-000000000001','e1500000-0000-4000-8000-000000000010',(date_trunc('month',now())-interval '1 month')::date,'[{"question":"q1","skipped":false,"value":5},{"question":"q2","skipped":false,"value":5},{"question":"q3","skipped":false,"value":5},{"question":"q4","skipped":false,"value":5}]'::jsonb from generate_series(1,4);
insert into p15 values('privacy',public.admin_analytics_workspace('e3200000-0000-4000-8000-000000000001',(date_trunc('month',now())-interval '1 month')::date,date_trunc('month',now())::date,'SANDBOX'));
select ok((select (v->'feedback'->0->>'suppressed')::boolean from p15 where k='privacy'),'analytics keeps small-group privacy suppression');
select is((select v->'feedback'->0->>'sample' from p15 where k='privacy'),null::text,'suppressed sample is unknown, not false zero');
select ok(not exists(select 1 from p15 where k='privacy' and (v->'feedback')::text~'customer_id|response_id|answers|telegram|source_response_ids'),'anonymous analytics never projects source identities or raw text');
select ok(not has_function_privilege('authenticated','public.consume_verified_payment(uuid,uuid)','execute'),'analytics does not expand payment authority');
insert into public.tenants(id,name,slug) values('e1500000-0000-4000-8000-000000000020','Synthetic complete costs','phase15-sandbox-complete');
insert into public.tenant_members(tenant_id,user_id,role) values('e1500000-0000-4000-8000-000000000020','e3100000-0000-4000-8000-000000000001','manager');
select pg_temp.phase15_seed('e1500000-0000-4000-8000-000000000020','e3100000-0000-4000-8000-000000000001',gen_random_uuid(),true);
select is((select (x->>'amount')::numeric from jsonb_array_elements(private.analytics_money('e1500000-0000-4000-8000-000000000020',current_date-30,current_date+1,'SANDBOX')) x where x->>'kind'='cost_per_operation'),0.20000002::numeric,'complete recorded billing / three successful operations exact numeric; never agent_runs duplicate costs');
select is((select x->>'status' from jsonb_array_elements(private.analytics_money('e1500000-0000-4000-8000-000000000020',current_date-30,current_date+1,'SANDBOX')) x where x->>'kind'='cost_per_operation'),'RECORDED_UNVERIFIED','complete telemetry never claims independent billing verification');
select is(jsonb_array_length(public.admin_analytics_sources('e3200000-0000-4000-8000-000000000001',current_date-30,current_date+1,'SANDBOX','invoices',(public.admin_analytics_workspace('e3200000-0000-4000-8000-000000000001',current_date-30,current_date+1,'SANDBOX')->>'fingerprint'))->'rows'),2,'cash drilldown contains only same verified two invoice sources as chart');
select is(length(public.admin_analytics_workspace('e3200000-0000-4000-8000-000000000001',current_date-30,current_date+1,'SANDBOX')->>'fingerprint'),64,'source revision uses SHA256');
select throws_ok($$select public.admin_analytics_sources('e3200000-0000-4000-8000-000000000001',current_date-30,current_date+1,'SANDBOX','anonymous',(public.admin_analytics_workspace('e3200000-0000-4000-8000-000000000001',current_date-30,current_date+1,'SANDBOX')->>'fingerprint'))$$,'22023','analytics source invalid','anonymous individual source drilldown does not exist');
set local timezone='Pacific/Auckland';
select is((public.admin_analytics_workspace('e3200000-0000-4000-8000-000000000001',(now() at time zone 'UTC')::date-7,(now() at time zone 'UTC')::date,'SANDBOX')->'series'->0->>'day'),((now() at time zone 'UTC')::date-7)::text,'UTC day labels independent of session timezone and DST');
reset timezone;
select is((select x->>'unit' from jsonb_array_elements(private.analytics_metrics('e3200000-0000-4000-8000-000000000001',current_date-30,current_date+1,'LIVE')) x where x->>'id'='margin'),'ratio','contribution margin is dimensionless, not an amount');
select is((select x->>'unit' from jsonb_array_elements(private.analytics_metrics('e3200000-0000-4000-8000-000000000001',current_date-30,current_date+1,'LIVE')) x where x->>'id'='roi'),'ratio','ROI is dimensionless, not an amount');
-- Disposable transaction only: a live-shaped period with no received-amount contract must not produce a sandbox MRR group.
insert into public.subscriptions(id,tenant_id,customer_id,plan_version_id,mode,state,plan_snapshot,commercial_snapshot,starts_at,ends_at,grace_until,renewal_due_at) values('e1500000-0000-4000-8000-000000000030','e3200000-0000-4000-8000-000000000001','e3300000-0000-4000-8000-000000000001','e3500000-0000-4000-8000-000000000002','live','ACTIVE','{}','{}',now()-interval '1 month',now()+interval '1 month',now()+interval '1 month',now()+interval '27 days');
insert into public.subscription_payments(tenant_id,subscription_id,mode,receipt_id,event_id,term_snapshot,period_start,period_end) values('e3200000-0000-4000-8000-000000000001','e1500000-0000-4000-8000-000000000030','live',((select v from p15 where k='local_receipt')#>>'{}')::uuid,((select v from p15 where k='local_receipt_event')#>>'{}')::uuid,'{"billing":"recurring","duration_unit":"calendar_month","duration_count":1}',now()-interval '1 month',now()+interval '1 month');
select ok(not exists(select 1 from jsonb_array_elements(private.analytics_money('e3200000-0000-4000-8000-000000000001',current_date-30,current_date+1,'LIVE')) x where x->>'kind' in ('mrr','arr')),'live period with unknown amount cannot masquerade as sandbox MRR');
select ok((public.admin_analytics_workspace('e3200000-0000-4000-8000-000000000001',current_date-30,current_date+1,'SANDBOX')->'cost_evidence'->0->>'reference') is not null,'manager can inspect evidence before reviewing costs');
select set_config('request.jwt.claim.sub','e3100000-0000-4000-8000-000000000003',true);
select ok((public.admin_analytics_workspace('e3200000-0000-4000-8000-000000000001',current_date-30,current_date+1,'SANDBOX')->'cost_evidence'->0->>'reference') is null,'analyst does not receive private economic source references');
select * from finish();
rollback;
